function escapeMarkdownV2(str) {
  if (!str) return '';
  return String(str).replace(/([_*[\]()~`>#+\-=|{}.!\\])/g, '\\$1');
}

const raw = $('Telegram_Trigger').first().json || {};
const cfg = $('User_Config').first().json || {};

let staticData = {};
try { staticData = $getWorkflowStaticData('global'); } catch (e) { staticData = {}; }
staticData.sessions = staticData.sessions || {};

let chatId = '';
let eventType = 'ignore';
let payload = {};

const getSession = (cid) => staticData.sessions[cid] || {};
const saveSession = (cid, data) => { staticData.sessions[cid] = data; };

// ── Welcome Message ──────────────────────────────────────────────────────
const makeWelcomeMessage = () => {
  const text = `🎬 *Welcome to Fluid Motion Studio\\!*\n\nI turn your concepts into cinematic AI video using state\\-of\\-the\\-art serverless workflows\\.\n\n🎭 *Available Character Rosters:*\n• *Pro Series:* Sam, Singh, Brock, Alen, Dana, Boo, Miga, Sia\n• *Diva Series:* Rani, Gemma, Miga, Dana, Boo, Sia\n• *Neutral:* Unlimited custom/original characters \\& worlds\n\n💡 *Quick Suggestions:*\n1\\. Cyberpunk transformation in neon rain with Sia\n2\\. Ghibli\\-style warm tea house morning with Alen\n3\\. High\\-fashion Paris runway walk with Gemma\n4\\. Tactical assault extraction with Sam \\& Singh\n5\\. Ethereal underwater ancient temple discovery\n\n👇 *Step 1: Choose your Video Universe:*`;
  const replyMarkup = {
    inline_keyboard: [
      [
        { text: '✨ Pro Character Universe', callback_data: 'type:pro' },
        { text: '💎 Diva Nation Glamor', callback_data: 'type:diva' }
      ],
      [{ text: '🎨 Neutral / Original Concept', callback_data: 'type:neutral' }],
      [{ text: '❌ Reset Session', callback_data: 'action:reset' }]
    ]
  };
  return { text, replyMarkup };
};

// ── Style Picker ──────────────────────────────────────────────────────────
const makeStylePicker = (videoType) => {
  const universe = videoType.toUpperCase();
  const text = `✅ *Universe selected:* ${escapeMarkdownV2(universe)}\n\n🎨 *Step 2: Choose your Visual Style:*\n\nThis defines the rendering mood \\— anime, cinematic, dark, etc\\.`;
  const replyMarkup = {
    inline_keyboard: [
      [
        { text: '🌸 Anime SDXL', callback_data: 'style:anime' },
        { text: '⚡ Cyberpunk Neon', callback_data: 'style:cyberpunk' }
      ],
      [
        { text: '🎬 Cinematic 35mm', callback_data: 'style:cinematic' },
        { text: '🕶️ Noir Film', callback_data: 'style:noir' }
      ],
      [
        { text: '🌿 Ghibli Watercolor', callback_data: 'style:ghibli' },
        { text: '📷 Photorealistic', callback_data: 'style:photorealistic' }
      ],
      [{ text: '❌ Reset', callback_data: 'action:reset' }]
    ]
  };
  return { text, replyMarkup };
};

// ── Resume Prompt ─────────────────────────────────────────────────────────
const getStageLabel = (s) => ({
  awaiting_idea: 'Awaiting Scene Idea',
  storyboard_review: 'Storyboard Review',
  image_approved: 'Reference Image Rendered',
  generating_video: 'Video Render Pipeline'
}[s] || 'Draft in Progress');

const makeResumePrompt = (session) => {
  const universe = escapeMarkdownV2((session.video_type || 'neutral').toUpperCase());
  const style = escapeMarkdownV2(session.style || 'not set');
  const stage = escapeMarkdownV2(getStageLabel(session.stage));
  const idea = escapeMarkdownV2((session.idea || 'Custom Concept').substring(0, 80));
  const text = `🔄 *Active Production Found\\!*\n\n• *Universe:* ${universe}\n• *Style:* ${style}\n• *Stage:* ${stage}\n• *Concept:* _"${idea}"_\n\n👇 *Resume or start fresh?*`;
  const replyMarkup = {
    inline_keyboard: [[
      { text: '▶️ Resume Production', callback_data: 'action:resume' },
      { text: '✨ Start Fresh', callback_data: 'action:reset' }
    ]]
  };
  return { text, replyMarkup };
};

// ── Idea Prompt ───────────────────────────────────────────────────────────
const makeIdeaPrompt = (videoType, style) => {
  const universe = escapeMarkdownV2(videoType.toUpperCase());
  const styleName = escapeMarkdownV2(style || '');
  return {
    text: `✅ *Universe:* ${universe} \\| *Style:* ${styleName}\n\n✍️ *Step 3: Send me your Story / Scene Concept*\n\nDescribe the action, characters, and mood\\. The AI will world\\-build and storyboard it automatically\\.\n\n*Example:*\n_"Sia leaps between neon\\-lit skyscrapers chasing a rogue drone\\. Rain\\. 3am\\."_`
  };
};

// ── MAIN DISPATCH ─────────────────────────────────────────────────────────
if (raw.callback_query) {
  chatId = String(raw.callback_query.message?.chat?.id || raw.callback_query.from?.id || '');
  const data = raw.callback_query.data || '';
  let session = getSession(chatId);

  if (data === 'action:reset') {
    saveSession(chatId, {});
    eventType = 'send_welcome';
    const w = makeWelcomeMessage();
    payload = { text: w.text, reply_markup: w.replyMarkup };

  } else if (data === 'action:resume') {
    if (session.stage === 'storyboard_review' && session.storyboard) {
      eventType = 'show_storyboard_cached';
      payload = { session, storyboard: session.storyboard };
    } else if (session.stage === 'image_approved' && session.reference_image_base64) {
      eventType = 'show_image_cached';
      payload = { session };
    } else if (session.stage === 'awaiting_idea') {
      eventType = 'send_message';
      payload = makeIdeaPrompt(session.video_type, session.style);
    } else {
      eventType = 'send_welcome';
      const w = makeWelcomeMessage();
      payload = { text: w.text, reply_markup: w.replyMarkup };
    }

  } else if (data.startsWith('type:')) {
    session.video_type = data.replace('type:', '');
    session.stage = 'selecting_style';
    saveSession(chatId, session);
    eventType = 'send_message';
    const sp = makeStylePicker(session.video_type);
    payload = { text: sp.text, reply_markup: sp.replyMarkup };

  } else if (data.startsWith('style:')) {
    session.style = data.replace('style:', '');
    session.stage = 'awaiting_idea';
    saveSession(chatId, session);
    eventType = 'send_message';
    payload = makeIdeaPrompt(session.video_type, session.style);

  } else if (data === 'action:approve_storyboard') {
