  } else if (data === 'action:regen_storyboard') {
    session.isRegen = true;
    saveSession(chatId, session);
    eventType = 'gen_world_and_storyboard';
    payload = { session, isRegen: true };

  } else if (data === 'action:confirm_image') {
    session.stage = 'generating_video';
    saveSession(chatId, session);
    eventType = 'gen_video';
    payload = { session };

  } else if (data === 'action:regen_image') {
    session.isRegenImage = true;
    saveSession(chatId, session);
    eventType = 'gen_image_draft';
    payload = { session, isRegenImage: true };
  }

} else if (raw.message && raw.message.text) {
  chatId = String(raw.message.chat?.id || raw.message.from?.id || '');
  const text = (raw.message.text || '').trim();
  const lower = text.toLowerCase();
  let session = getSession(chatId);

  const resets = ['/reset', 'reset', '/clear', 'clear'];
  const resumes = ['/resume', 'resume'];
  const greetings = ['hey', 'hi', 'hello', 'start', '/start', 'help', '/help', 'menu'];

  if (resets.includes(lower)) {
    saveSession(chatId, {});
    eventType = 'send_welcome';
    const w = makeWelcomeMessage();
    payload = { text: w.text, reply_markup: w.replyMarkup };

  } else if (resumes.includes(lower)) {
    if (session.stage && session.stage !== 'completed') {
      const r = makeResumePrompt(session);
      eventType = 'send_welcome';
      payload = { text: r.text, reply_markup: r.replyMarkup };
    } else {
      eventType = 'send_welcome';
      const w = makeWelcomeMessage();
      payload = { text: w.text, reply_markup: w.replyMarkup };
    }

  } else if (greetings.includes(lower)) {
    if (session.stage && (session.storyboard || session.idea)) {
      const r = makeResumePrompt(session);
      eventType = 'send_welcome';
      payload = { text: r.text, reply_markup: r.replyMarkup };
    } else {
      saveSession(chatId, {});
      eventType = 'send_welcome';
      const w = makeWelcomeMessage();
      payload = { text: w.text, reply_markup: w.replyMarkup };
    }

  } else if (!session.video_type) {
    eventType = 'send_welcome';
    const w = makeWelcomeMessage();
    payload = { text: w.text, reply_markup: w.replyMarkup };

  } else if (session.stage === 'selecting_style' || !session.style) {
    // User typed instead of clicking style — treat as style text or re-prompt
    const styleMap = { anime: 'anime', cyberpunk: 'cyberpunk', cinematic: 'cinematic', noir: 'noir', ghibli: 'ghibli', photorealistic: 'photorealistic' };
    const matchedStyle = styleMap[lower] || null;
    if (matchedStyle) {
