// Convert Markdown to Telegraph NodeElement array with strict validation
function mdToTelegraphNodes(md) {
  const lines = (md || '').split('\n');
  const nodes = [];
  let ulBuffer = [];

  const flushUl = () => {
    if (ulBuffer.length > 0) {
      const items = ulBuffer.filter(t => t && t.trim().length > 0);
      if (items.length > 0) {
        nodes.push({ tag: 'ul', children: items.map(t => ({ tag: 'li', children: [t] })) });
      }
      ulBuffer = [];
    }
  };

  for (const raw of lines) {
    const line = raw.trim();
    if (!line) { flushUl(); continue; }

    if (/^#{1,2}\s/.test(line)) {
      flushUl();
      const text = line.replace(/^#{1,2}\s+/, '').trim();
      if (text) nodes.push({ tag: 'h3', children: [text] });
    } else if (/^#{3,4}\s/.test(line)) {
      flushUl();
      const text = line.replace(/^#{3,4}\s+/, '').trim();
      if (text) nodes.push({ tag: 'h4', children: [text] });
    } else if (/^[-*•]\s/.test(line)) {
      const text = line.replace(/^[-*•]\s+/, '').replace(/\*\*(.+?)\*\*/g, '$1').trim();
      if (text) ulBuffer.push(text);
    } else if (/^\*\*(.+)\*\*$/.test(line)) {
      flushUl();
      const text = line.replace(/\*\*/g, '').trim();
      if (text) nodes.push({ tag: 'h4', children: [text] });
    } else if (/^Frame\s+\d+/i.test(line)) {
      flushUl();
      const text = line.replace(/[*#]/g, '').trim();
      nodes.push({ tag: 'h3', children: [text] });
    } else {
      flushUl();
      const text = line.replace(/\*\*(.+?)\*\*/g, '$1').replace(/\*(.+?)\*/g, '$1').trim();
      if (text) nodes.push({ tag: 'p', children: [text] });
    }
  }
  flushUl();
  return nodes.length > 0 ? nodes : [{ tag: 'p', children: ['Storyboard generation completed.'] }];
}

