        [{ text: '🔄 Retry', callback_data: 'action:regen_storyboard' }],
        [{ text: '❌ Start Over', callback_data: 'action:reset' }]
      ]}
    }
  }];
} else if (item.choices?.[0]?.message?.content) {
  rawResponse = item.choices[0].message.content;
} else if (typeof item.storyboard === 'string') {
  rawResponse = item.storyboard;
} else if (session.storyboard) {
  rawResponse = session.storyboard;
} else {
  return [{ json: { ...item, chat_id: chatId, telegram_bot_token: token, is_error: true,
    send_text: '⚠️ *No storyboard content returned from AI model\\.*',
    reply_markup: { inline_keyboard: [[{ text: '🔄 Retry', callback_data: 'action:regen_storyboard' }]] }
  }}];
}

// ── Parse 3 sections from LLM output ───────────────────────────
let worldSheet = null;
const jsonMatch = rawResponse.match(/```json\s*([\s\S]*?)```/i);
if (jsonMatch) {
  try { worldSheet = JSON.parse(jsonMatch[1]); } catch(e) { worldSheet = null; }
}

let storyboardText = '';
const sb2Match = rawResponse.match(/##\s*SECTION\s*2[^\n]*\n([\s\S]*?)(?=##\s*SECTION\s*3|IMAGE_PROMPT:|$)/i);
if (sb2Match) {
  storyboardText = sb2Match[1].trim();
} else {
  const frameStart = rawResponse.search(/(?:\*\*|###?\s*)Frame\s*1/i);
  const imgStart = rawResponse.search(/IMAGE_PROMPT:/i);
  if (frameStart >= 0) {
    storyboardText = rawResponse.slice(frameStart, imgStart > 0 ? imgStart : undefined).trim();
  } else {
    storyboardText = rawResponse;
  }
}

const frameMatches = storyboardText.match(/(?:\*\*|###?\s*)Frame\s*\d+/gi) || [];
const frameCount = frameMatches.length || 6;

let imagePrompt = '';
const imgMatch = rawResponse.match(/IMAGE_PROMPT:\s*([\s\S]*?)$/i);
if (imgMatch) {
  imagePrompt = imgMatch[1].trim();
}

// ── Save to session ────────────────────────────────────────────
session.worldSheet = worldSheet;
session.storyboard = storyboardText;
session.imagePrompt = imagePrompt;
session.frameCount = frameCount;
session.stage = 'storyboard_review';

// ── Publish / In-Place Update to Telegraph ─────────────────────
const ideaSnippet = (session.idea || 'Concept').substring(0, 60);
const telegraphTitle = `${(session.video_type || 'Neutral').toUpperCase()} · ${(session.style || 'Cinematic').toUpperCase()} — ${ideaSnippet}`;
const telegraphContent = mdToTelegraphNodes(storyboardText);

let telegraphUrl = session.telegraph_url || null;
let telegraphPath = session.telegraph_path || null;
let telegraphDebug = { attempted: false };

if (telegraphToken) {
  telegraphDebug.attempted = true;
  const isUpdate = !!telegraphPath;
  const endpoint = isUpdate ? 'https://api.telegra.ph/editPage' : 'https://api.telegra.ph/createPage';
  const reqPayload = {
    access_token: telegraphToken,
    title: telegraphTitle,
    author_name: 'Fluid Motion Studio',
    content: telegraphContent,
    return_content: false,
    ...(isUpdate ? { path: telegraphPath } : {})
  };

  // Attempt 1: this.helpers.httpRequest with both data & body (Axios compatibility)
  try {
    let tRes = await this.helpers.httpRequest({
      method: 'POST',
      url: endpoint,
      headers: { 'Content-Type': 'application/json' },
      data: reqPayload,
      body: reqPayload,
      json: true
    });
    if (typeof tRes === 'string') {
      try { tRes = JSON.parse(tRes); } catch(err) {}
    }
    const resData = tRes?.data || tRes;
    telegraphDebug.attempt1_res = resData?.ok ? 'ok' : (resData?.error || 'not_ok');
    if (resData?.ok && resData?.result) {
      telegraphUrl = resData.result.url;
      telegraphPath = resData.result.path || (resData.result.url ? resData.result.url.replace(/^https?:\/\/telegra\.ph\//, '') : telegraphPath);
    }
  } catch(e1) {
    telegraphDebug.attempt1_err = e1.message || String(e1);
  }

  // Attempt 2: Fallback to createPage with stringified data if attempt 1 did not get a URL
  if (!telegraphUrl) {
    try {
      let tRes2 = await this.helpers.httpRequest({
        method: 'POST',
        url: 'https://api.telegra.ph/createPage',
        headers: { 'Content-Type': 'application/json' },
        data: JSON.stringify({
          access_token: telegraphToken,
          title: telegraphTitle,
          author_name: 'Fluid Motion Studio',
          content: telegraphContent,
          return_content: false
        }),
        body: JSON.stringify({
          access_token: telegraphToken,
          title: telegraphTitle,
          author_name: 'Fluid Motion Studio',
          content: telegraphContent,
          return_content: false
        })
      });
      if (typeof tRes2 === 'string') {
        try { tRes2 = JSON.parse(tRes2); } catch(err) {}
      }
      const resData2 = tRes2?.data || tRes2;
      telegraphDebug.attempt2_res = resData2?.ok ? 'ok' : (resData2?.error || 'not_ok');
      if (resData2?.ok && resData2?.result) {
        telegraphUrl = resData2.result.url;
        telegraphPath = resData2.result.path || (resData2.result.url ? resData2.result.url.replace(/^https?:\/\/telegra\.ph\//, '') : null);
      }
    } catch(e2) {
      telegraphDebug.attempt2_err = e2.message || String(e2);
    }
  }

  // Attempt 3: Native global fetch fallback
  if (!telegraphUrl && typeof fetch === 'function') {
    try {
      const fRes = await fetch('https://api.telegra.ph/createPage', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          access_token: telegraphToken,
          title: telegraphTitle,
          author_name: 'Fluid Motion Studio',
          content: telegraphContent,
          return_content: false
        })
      });
      const fData = await fRes.json();
      telegraphDebug.attempt3_res = fData?.ok ? 'ok' : (fData?.error || 'not_ok');
      if (fData?.ok && fData?.result) {
        telegraphUrl = fData.result.url;
        telegraphPath = fData.result.path || (fData.result.url ? fData.result.url.replace(/^https?:\/\/telegra\.ph\//, '') : null);
      }
    } catch(e3) {
      telegraphDebug.attempt3_err = e3.message || String(e3);
    }
  }
}

// Persist Telegraph details in session
if (telegraphPath) session.telegraph_path = telegraphPath;
if (telegraphUrl) session.telegraph_url = telegraphUrl;
staticData.sessions[chatId] = session;

// ── Build Telegram message ─────────────────────────────────────
const styleLabel = escapeMarkdownV2((session.style || 'cinematic').toUpperCase());
const universeLabel = escapeMarkdownV2((session.video_type || 'neutral').toUpperCase());
const frameLabel = escapeMarkdownV2(String(frameCount));
const ideaLabel = escapeMarkdownV2(ideaSnippet);

const replyMarkup = {
  inline_keyboard: [
    [
      { text: '✅ Approve & Generate Image', callback_data: 'action:approve_storyboard' },
      { text: '🔄 Regenerate', callback_data: 'action:regen_storyboard' }
    ],
    [{ text: '❌ Start Over', callback_data: 'action:reset' }]
  ]
};

let sendText;
if (telegraphUrl) {
  sendText = `🎬 *Storyboard Ready\\!*

*Universe:* ${universeLabel} \\| *Style:* ${styleLabel}
*Frames:* ${frameLabel} panels
*Concept:* _${ideaLabel}_

📖 [View Full Storyboard](${telegraphUrl})

👇 *Approve to generate the storyboard image:*`;
