  sendText = `🎬 *Storyboard Ready \\(${frameLabel} frames\\)\\!*

*Universe:* ${universeLabel} \\| *Style:* ${styleLabel}

_${safeSnippet}\\.\\.\\._

👇 *Approve to generate the image:*`;
}

return [{
  json: {
    ...item,
    chat_id: chatId,
    telegram_bot_token: token,
    is_error: false,
    telegraph_url: telegraphUrl,
    telegraph_path: telegraphPath,
    telegraph_debug: telegraphDebug,
