// Determine prompt source
let sourcePrompt = session.imagePrompt || session.idea || 'cinematic scene';
// If imagePrompt wasn't extracted properly and we have to rely on storyboard, clean it up
if (sourcePrompt.length > 800) {
    sourcePrompt = sourcePrompt.substring(0, 800).replace(/[*#_~]/g, '');
