}

const item = $json || {};
const dispatcher = $('Dispatcher_And_State').first().json || {};
const cfg = $('User_Config').first().json || {};

const chatId = dispatcher.chat_id || item.chat_id || '';
const token = cfg.telegram_bot_token || dispatcher.telegram_bot_token || item.telegram_bot_token || '';

let staticData = {};
try { staticData = $getWorkflowStaticData('global'); } catch(e) {}
staticData.sessions = staticData.sessions || {};
let session = staticData.sessions[chatId] || dispatcher.session || {};

let base64Data = '';
if (item.output && item.output.images && item.output.images[0] && item.output.images[0].data) {
  base64Data = item.output.images[0].data;
} else if (item.images && item.images[0] && item.images[0].data) {
  base64Data = item.images[0].data;
} else if (item.output && item.output.image) {
  base64Data = item.output.image;
} else if (item.image) {
  base64Data = item.image;
} else if (item.reference_image_base64) {
  base64Data = item.reference_image_base64;
} else if (session.reference_image_base64) {
  base64Data = session.reference_image_base64;
}

let isError = !base64Data;
let errorMessage = '';

if (isError) {
  errorMessage = item.error ? (item.error.message || JSON.stringify(item.error)) : (item.status === 'FAILED' ? 'RunPod job status: FAILED' : 'No image data returned from RunPod SDXL worker.');
} else {
  session.reference_image_base64 = base64Data;
  session.stage = 'image_approved';
  staticData.sessions[chatId] = session;
}

const caption = isError
  ? `⚠️ *RunPod Image Worker Error:*\n\n\`${escapeMarkdownV2(errorMessage)}\`\n\n👇 *Choose an action to retry:*`
  : `✨ *Reference Image Rendered \\(Stage V3\\)*\n\n• *Model:* Animagine XL 4\\.0 SDXL\n• *Resolution:* 1280x720 \\(Landscape\\)\n\n👇 *Proceed to generate video:*`;

const replyMarkup = isError
  ? {
      inline_keyboard: [
        [{ text: '🔄 Retry Image Render', callback_data: 'action:regen_image' }],
        [{ text: '❌ Start Over', callback_data: 'action:reset' }]
      ]
    }
  : {
      inline_keyboard: [
        [
          { text: '🎬 Generate Video (Stage V4)', callback_data: 'action:confirm_image' },
          { text: '🔄 Re-roll Image', callback_data: 'action:regen_image' }
        ],
        [
          { text: '❌ Start Over', callback_data: 'action:reset' }
        ]
      ]
    };

const result = {
  json: {
    ...item,
    chat_id: chatId,
    telegram_bot_token: token,
    is_error: isError,
    error_message: errorMessage,
    caption: caption,
    send_text: caption,
    reply_markup: replyMarkup
  }
};

if (base64Data) {
  if (base64Data.includes(",")) base64Data = base64Data.split(",")[1];
  result.binary = {
    photo: {
      data: base64Data,
      mimeType: 'image/png',
      fileName: 'reference_character.png'
    }
  };
}

return [result];
